        while not isb(d):
            d = d + D1
        return d
    def addb(d, n):
        c = 0
        while c < n:
            d = d + D1
            if isb(d):
                c += 1
        return d
    def say(d):
        return DN[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year) + ' (' + d.isoformat() + ')'
    def money(x):
        return '{:,.2f}'.format(float(x))
