    elif t == 'personal_loan':
        phrase = 'personal loan'; floor = p.get('instalment_amount'); floor_name = 'the instalment amount'
    elif t == 'car_loan':
        phrase = 'car loan'; floor = p.get('instalment_amount'); floor_name = 'the instalment amount'
    else:
