    f.append('- Today: ' + say(today) + ', time ' + now.strftime('%H:%M') + '.')
    f.append('- DEADLINE (latest date you may record): ' + say(deadline) + '.')
    f.append('- Persuasion attempts allowed: ' + str(attempts) + '.')
